<template>
  <section class="section-block session-panel">
    <div class="section-heading">
      <div>
        <span class="eyebrow">SESSION SCHEDULE</span>
        <h3 class="section-title">세션 일정</h3>
      </div>
    </div>
    <p class="muted">
      날짜와 시간은 한국 시간입니다. 알림 설정에서 세션 알림을 켜면 시작 10분
      전에 알려드립니다.
    </p>
    <form v-if="isGM" class="session-form" @submit.prevent="save">
      <label
        >세션 이름<input
          v-model.trim="title"
          class="form-input"
          maxlength="120"
          required
          placeholder="예: 3회차 세션"
      /></label>
      <label
        >날짜와 시간 (한국 시간)<input
          v-model="starts"
          class="form-input"
          type="datetime-local"
          required
      /></label>
      <button class="primary-button" :disabled="busy">
        {{ editing ? "일정 수정" : "일정 등록" }}
      </button>
      <button
        v-if="editing"
        type="button"
        class="outline-button"
        @click="reset"
      >
        수정 취소
      </button>
    </form>
    <p v-if="error" role="alert">{{ error }}</p>
    <p v-if="loading" class="empty-state">일정을 불러오는 중…</p>
    <p v-else-if="!sessions.length" class="empty-state">
      예정된 세션이 없습니다.
    </p>
    <div v-for="session in sessions" :key="session.id" class="session-row">
      <div>
        <strong>{{ session.title }}</strong>
        <p>{{ formatDate(session.starts_at) }}</p>
      </div>
      <div v-if="isGM" class="session-actions">
        <button class="text-button" :disabled="busy" @click="edit(session)">
          수정</button
        ><button class="text-button" :disabled="busy" @click="cancel(session)">
          일정 취소
        </button>
      </div>
    </div>
    <router-link to="/notifications" class="text-button"
      >🔔 알림 설정 →</router-link
    >
  </section>
</template>
<script>
import { supabase } from "@/supabase";
export default {
  props: { teamId: { type: String, required: true } },
  data: () => ({
    sessions: [],
    loading: false,
    busy: false,
    error: "",
    title: "",
    starts: "",
    editing: null,
  }),
  computed: {
    isGM() {
      return this.$store.getters.isGM;
    },
  },
  watch: {
    teamId: {
      immediate: true,
      handler() {
        this.reset();
        this.load();
      },
    },
  },
  mounted() {
    window.addEventListener("focus", this.load);
  },
  beforeUnmount() {
    window.removeEventListener("focus", this.load);
  },
  methods: {
    async load() {
      this.loading = true;
      this.error = "";
      try {
        const { data, error } = await supabase
          .from("team_sessions")
          .select("*")
          .eq("team_id", this.teamId)
          .eq("cancelled", false)
          .gt("starts_at", new Date().toISOString())
          .order("starts_at");
        if (error) throw error;
        this.sessions = data || [];
      } catch (e) {
        this.error = `일정 조회 실패: ${e.message}`;
      } finally {
        this.loading = false;
      }
    },
    reset() {
      this.title = "";
      this.starts = "";
      this.editing = null;
    },
    edit(session) {
      this.editing = session.id;
      this.title = session.title;
      this.starts = new Date(Date.parse(session.starts_at) + 9 * 3600000)
        .toISOString()
        .slice(0, 16);
    },
    formatDate(value) {
      return new Intl.DateTimeFormat("ko-KR", {
        timeZone: "Asia/Seoul",
        dateStyle: "full",
        timeStyle: "short",
      }).format(new Date(value));
    },
    async save() {
      const time = new Date(`${this.starts}:00+09:00`);
      if (
        !this.title ||
        !Number.isFinite(time.getTime()) ||
        time.getTime() <= Date.now()
      ) {
        this.error = "세션 이름과 미래의 날짜·시간을 입력하세요.";
        return;
      }
      this.busy = true;
      this.error = "";
      try {
        const row = {
          team_id: this.teamId,
          title: this.title,
          starts_at: time.toISOString(),
        };
        const result = this.editing
          ? await supabase
              .from("team_sessions")
              .update(row)
              .eq("id", this.editing)
          : await supabase.from("team_sessions").insert(row);
        if (result.error) throw result.error;
        this.reset();
        await this.load();
      } catch (e) {
        this.error = `일정 저장 실패: ${e.message}`;
      } finally {
        this.busy = false;
      }
    },
    async cancel(session) {
      if (!window.confirm(`${session.title} 일정을 취소할까요?`)) return;
      this.busy = true;
      try {
        const { error } = await supabase
          .from("team_sessions")
          .update({ cancelled: true })
          .eq("id", session.id);
        if (error) throw error;
        if (this.editing === session.id) this.reset();
        await this.load();
      } catch (e) {
        this.error = e.message;
      } finally {
        this.busy = false;
      }
    },
  },
};
</script>
